/*
 * Optimized implementations of string methods for numpy arrays.
 *
 * These functions operate directly on the raw Unicode data without
 * creating Python objects for each element, providing significant
 * speedups for large arrays.
 */

#define NPY_NO_DEPRECATED_API NPY_API_VERSION
#define _MULTIARRAYMODULE

#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include "numpy/arrayobject.h"
#include "npy_pycompat.h"

/*
 * Character classification helpers for ASCII range.
 * These are much faster than calling Python methods.
 */

static NPY_INLINE int
npy_ascii_isalpha(npy_ucs4 ch)
{
    return (ch < 128) && ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z'));
}

static NPY_INLINE int
npy_ascii_isdigit(npy_ucs4 ch)
{
    return (ch < 128) && (ch >= '0' && ch <= '9');
}

static NPY_INLINE int
npy_ascii_isalnum(npy_ucs4 ch)
{
    return npy_ascii_isalpha(ch) || npy_ascii_isdigit(ch);
}

static NPY_INLINE int
npy_ascii_isspace(npy_ucs4 ch)
{
    return (ch < 128) && (ch == ' ' || ch == '\t' || ch == '\n' ||
                          ch == '\r' || ch == '\f' || ch == '\v');
}

static NPY_INLINE int
npy_ascii_islower(npy_ucs4 ch)
{
    return (ch < 128) && (ch >= 'a' && ch <= 'z');
}

static NPY_INLINE int
npy_ascii_isupper(npy_ucs4 ch)
{
    return (ch < 128) && (ch >= 'A' && ch <= 'Z');
}

static NPY_INLINE int
npy_ascii_istitle_char(npy_ucs4 ch)
{
    /* Titlecase characters are uppercase for our purposes */
    return npy_ascii_isupper(ch);
}

static NPY_INLINE int
npy_ascii_is_cased(npy_ucs4 ch)
{
    return npy_ascii_islower(ch) || npy_ascii_isupper(ch);
}

/*
 * Check if all characters in the string are ASCII.
 * Returns 1 if all ASCII, 0 otherwise.
 * len is the number of UCS-4 characters (not bytes).
 */
static NPY_INLINE int
is_all_ascii(const npy_ucs4 *str, int len)
{
    for (int i = 0; i < len; i++) {
        if (str[i] >= 128) {
            return 0;
        }
    }
    return 1;
}

/*
 * Get the actual length of a string (excluding trailing nulls).
 */
static NPY_INLINE int
get_string_length(const npy_ucs4 *str, int max_len)
{
    int len = max_len;
    while (len > 0 && str[len - 1] == 0) {
        len--;
    }
    return len;
}

/*
 * Optimized isalpha implementation.
 * Returns 1 if all characters are alphabetic and there is at least one character.
 */
static int
string_isalpha(const npy_ucs4 *str, int max_len)
{
    int len = get_string_length(str, max_len);
    if (len == 0) {
        return 0;
    }

    if (is_all_ascii(str, len)) {
        /* Fast ASCII path */
        for (int i = 0; i < len; i++) {
            if (!npy_ascii_isalpha(str[i])) {
                return 0;
            }
        }
        return 1;
    }

    /* Non-ASCII: fall back to Python */
    PyObject *pystr = PyUnicode_FromKindAndData(PyUnicode_4BYTE_KIND,
                                                 (const void *)str, len);
    if (pystr == NULL) {
        return -1;  /* Error */
    }
    int result = PyUnicode_IsAlpha(pystr);
    Py_DECREF(pystr);
    return result;
}

/*
 * Optimized isdigit implementation.
 */
static int
string_isdigit(const npy_ucs4 *str, int max_len)
{
    int len = get_string_length(str, max_len);
    if (len == 0) {
        return 0;
    }

    if (is_all_ascii(str, len)) {
        for (int i = 0; i < len; i++) {
