/*
 * Optimized islower implementation.
 */
static int
string_islower(const npy_ucs4 *str, int max_len)
{
    int len = get_string_length(str, max_len);
    if (len == 0) {
        return 0;
    }

    if (is_all_ascii(str, len)) {
        int has_cased = 0;
        for (int i = 0; i < len; i++) {
            npy_ucs4 ch = str[i];
            if (npy_ascii_isupper(ch)) {
                return 0;
            }
            if (npy_ascii_islower(ch)) {
                has_cased = 1;
            }
        }
        return has_cased;
    }

    PyObject *pystr = PyUnicode_FromKindAndData(PyUnicode_4BYTE_KIND,
                                                 (const void *)str, len);
    if (pystr == NULL) {
        return -1;
    }
    int result = PyUnicode_IsLower(pystr);
    Py_DECREF(pystr);
    return result;
}

/*
 * Optimized isupper implementation.
 */
static int
string_isupper(const npy_ucs4 *str, int max_len)
{
    int len = get_string_length(str, max_len);
    if (len == 0) {
        return 0;
    }

    if (is_all_ascii(str, len)) {
        int has_cased = 0;
        for (int i = 0; i < len; i++) {
            npy_ucs4 ch = str[i];
            if (npy_ascii_islower(ch)) {
                return 0;
            }
            if (npy_ascii_isupper(ch)) {
                has_cased = 1;
            }
        }
        return has_cased;
    }

    PyObject *pystr = PyUnicode_FromKindAndData(PyUnicode_4BYTE_KIND,
                                                 (const void *)str, len);
    if (pystr == NULL) {
        return -1;
    }
    int result = PyUnicode_IsUpper(pystr);
    Py_DECREF(pystr);
    return result;
}

/*
 * Optimized istitle implementation.
 */
static int
string_istitle(const npy_ucs4 *str, int max_len)
{
    int len = get_string_length(str, max_len);
    if (len == 0) {
        return 0;
    }

    if (is_all_ascii(str, len)) {
        int has_cased = 0;
        int previous_is_cased = 0;

        for (int i = 0; i < len; i++) {
            npy_ucs4 ch = str[i];
            if (npy_ascii_isupper(ch)) {
                if (previous_is_cased) {
                    return 0;  /* Uppercase after cased char - not title */
                }
                has_cased = 1;
                previous_is_cased = 1;
            } else if (npy_ascii_islower(ch)) {
                if (!previous_is_cased) {
                    return 0;  /* Lowercase without preceding uppercase */
                }
                has_cased = 1;
                previous_is_cased = 1;
            } else {
                previous_is_cased = 0;
            }
        }
        return has_cased;
    }

    PyObject *pystr = PyUnicode_FromKindAndData(PyUnicode_4BYTE_KIND,
                                                 (const void *)str, len);
    if (pystr == NULL) {
        return -1;
    }
    int result = PyUnicode_IsTitle(pystr);
    Py_DECREF(pystr);
    return result;
}

