 * Optimized isnumeric implementation.
 */
static int
string_isnumeric(const npy_ucs4 *str, int max_len)
{
    int len = get_string_length(str, max_len);
    if (len == 0) {
        return 0;
    }

    if (is_all_ascii(str, len)) {
        for (int i = 0; i < len; i++) {
