/*
 * Optimized isdecimal implementation.
 */
static int
string_isdecimal(const npy_ucs4 *str, int max_len)
{
    int len = get_string_length(str, max_len);
    if (len == 0) {
        return 0;
    }

    if (is_all_ascii(str, len)) {
