/*
 * Enum for the different string methods we optimize.
 */
typedef enum {
    STRING_METHOD_ISALPHA,
    STRING_METHOD_ISDIGIT,
    STRING_METHOD_ISALNUM,
    STRING_METHOD_ISSPACE,
    STRING_METHOD_ISLOWER,
    STRING_METHOD_ISUPPER,
    STRING_METHOD_ISTITLE,
    STRING_METHOD_ISNUMERIC,
    STRING_METHOD_ISDECIMAL,
    STRING_METHOD_COUNT
} string_method_id;

/*
 * Function pointer type for string method implementations.
 */
typedef int (*string_method_func)(const npy_ucs4 *str, int max_len);

/*
 * Table of optimized string method implementations.
 */
static string_method_func string_method_table[STRING_METHOD_COUNT] = {
    string_isalpha,
    string_isdigit,
    string_isalnum,
    string_isspace,
    string_islower,
    string_isupper,
    string_istitle,
    string_isnumeric,
    string_isdecimal,
};

/*
 * Get the method ID from a method name, or -1 if not optimized.
 */
static int
get_string_method_id(const char *method_name)
{
    if (strcmp(method_name, "isalpha") == 0) return STRING_METHOD_ISALPHA;
    if (strcmp(method_name, "isdigit") == 0) return STRING_METHOD_ISDIGIT;
    if (strcmp(method_name, "isalnum") == 0) return STRING_METHOD_ISALNUM;
    if (strcmp(method_name, "isspace") == 0) return STRING_METHOD_ISSPACE;
    if (strcmp(method_name, "islower") == 0) return STRING_METHOD_ISLOWER;
    if (strcmp(method_name, "isupper") == 0) return STRING_METHOD_ISUPPER;
    if (strcmp(method_name, "istitle") == 0) return STRING_METHOD_ISTITLE;
    if (strcmp(method_name, "isnumeric") == 0) return STRING_METHOD_ISNUMERIC;
    if (strcmp(method_name, "isdecimal") == 0) return STRING_METHOD_ISDECIMAL;
    return -1;
}

/*
 * Main optimized loop for string methods on Unicode arrays.
 * This is the core function that processes the array.
 */
static PyObject *
_vec_string_unicode_optimized(PyArrayObject *char_array,
                               PyArray_Descr *type,
                               string_method_id method_id)
{
    PyArrayIterObject *in_iter = NULL;
    PyArrayObject *result = NULL;
    PyArrayIterObject *out_iter = NULL;
    string_method_func func = string_method_table[method_id];

    /* Number of UCS-4 characters per element */
    int max_len = PyArray_ITEMSIZE(char_array) / sizeof(npy_ucs4);

    in_iter = (PyArrayIterObject *)PyArray_IterNew((PyObject *)char_array);
    if (in_iter == NULL) {
        Py_DECREF(type);
        goto err;
    }

    result = (PyArrayObject *)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        goto err;
    }

    out_iter = (PyArrayIterObject *)PyArray_IterNew((PyObject *)result);
    if (out_iter == NULL) {
        goto err;
    }

    while (PyArray_ITER_NOTDONE(in_iter)) {
        const npy_ucs4 *str = (const npy_ucs4 *)in_iter->dataptr;
        int res = func(str, max_len);

        if (res < 0) {
            /* Python error occurred */
            goto err;
        }

        npy_bool *out_ptr = (npy_bool *)PyArray_ITER_DATA(out_iter);
        *out_ptr = (npy_bool)res;

        PyArray_ITER_NEXT(in_iter);
        PyArray_ITER_NEXT(out_iter);
    }

    Py_DECREF(in_iter);
    Py_DECREF(out_iter);

    return (PyObject *)result;

err:
    Py_XDECREF(in_iter);
    Py_XDECREF(out_iter);
    Py_XDECREF(result);
    return NULL;
}

/*
 * Public API function: optimized version of _vec_string for Unicode arrays.
 *
 * This function is called from Python when an optimized string method
 * is detected. It handles the dispatch to the appropriate optimized
 * implementation.
 *
 * Arguments:
 *   char_array: The input Unicode array
 *   type: The output dtype (should be bool)
 *   method_name: The name of the string method (e.g., "isalpha")
 *
 * Returns:
 *   A new boolean array with the results, or NULL on error.
 *   If the method is not optimized, returns Py_None (borrowed reference)
 *   to indicate the caller should fall back to the generic implementation.
 */
NPY_NO_EXPORT PyObject *
_vec_string_unicode(PyObject *NPY_UNUSED(dummy), PyObject *args)
{
    PyArrayObject *char_array = NULL;
    PyArray_Descr *type = NULL;
    PyObject *method_name_obj = NULL;
    const char *method_name;
    int method_id;

    if (!PyArg_ParseTuple(args, "O&O&O",
                PyArray_Converter, &char_array,
                PyArray_DescrConverter, &type,
                &method_name_obj)) {
        return NULL;
    }

    /* Only handle Unicode arrays */
    if (PyArray_TYPE(char_array) != NPY_UNICODE) {
        Py_DECREF(type);
        Py_DECREF(char_array);
        Py_RETURN_NONE;
    }

    /* Get the method name as a C string */
    method_name = PyUnicode_AsUTF8(method_name_obj);
    if (method_name == NULL) {
        Py_DECREF(type);
        Py_DECREF(char_array);
        return NULL;
    }

