/*
 * Character classification helpers for ASCII range.
 * These are much faster than calling Python methods.
 */

static NPY_INLINE int
npy_ascii_isalpha(npy_ucs4 ch)
{
    return (ch < 128) && ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z'));
}

static NPY_INLINE int
npy_ascii_isdigit(npy_ucs4 ch)
{
    return (ch < 128) && (ch >= '0' && ch <= '9');
}

static NPY_INLINE int
npy_ascii_isalnum(npy_ucs4 ch)
{
    return npy_ascii_isalpha(ch) || npy_ascii_isdigit(ch);
}

static NPY_INLINE int
npy_ascii_isspace(npy_ucs4 ch)
{
    return (ch < 128) && (ch == ' ' || ch == '\t' || ch == '\n' ||
                          ch == '\r' || ch == '\f' || ch == '\v');
}

static NPY_INLINE int
npy_ascii_islower(npy_ucs4 ch)
{
    return (ch < 128) && (ch >= 'a' && ch <= 'z');
}

static NPY_INLINE int
npy_ascii_isupper(npy_ucs4 ch)
{
    return (ch < 128) && (ch >= 'A' && ch <= 'Z');
}

static NPY_INLINE int
npy_ascii_is_cased(npy_ucs4 ch)
{
    return npy_ascii_islower(ch) || npy_ascii_isupper(ch);
}

/*
 * Check if all characters in the string are ASCII.
 * Returns 1 if all ASCII, 0 otherwise.
 * len is the number of UCS-4 characters (not bytes).
 */
static NPY_INLINE int
is_all_ascii(const npy_ucs4 *str, int len)
{
    for (int i = 0; i < len; i++) {
        if (str[i] >= 128) {
            return 0;
        }
    }
    return 1;
}

/*
 * Get the actual length of a string (excluding trailing nulls).
 */
static NPY_INLINE int
get_string_length(const npy_ucs4 *str, int max_len)
{
    int len = max_len;
    while (len > 0 && str[len - 1] == 0) {
        len--;
    }
    return len;
}

/*
 * Create a Python Unicode object from raw UCS-4 data.
 */
static NPY_INLINE PyObject *
create_pyunicode(const npy_ucs4 *str, int len)
{
    return PyUnicode_FromKindAndData(PyUnicode_4BYTE_KIND,
                                     (const void *)str, len);
}

