 * Call a Python method on a string and return the boolean result.
 * Returns -1 on error.
 */
static NPY_INLINE int
call_string_method(PyObject *pystr, const char *method_name)
{
    PyObject *result = PyObject_CallMethod(pystr, method_name, NULL);
    if (result == NULL) {
        return -1;
    }
    int ret = PyObject_IsTrue(result);
    Py_DECREF(result);
    return ret;
}

